mapper.select:
SELECT u.id student_id, u.username, u.name, u.major_id, u.class_id, u.cohort, m.name major_name, c.name class_name, a.topic_id, a.teacher_id, t.title topic_title, teacher.name teacher_name FROM sys_user u JOIN sys_user_role ur ON ur.user_id = u.id JOIN sys_role r ON r.id = ur.role_id AND r.code = 'STUDENT' LEFT JOIN major m ON m.id = u.major_id LEFT JOIN school_class c ON c.id = u.class_id LEFT JOIN student_assignment a ON a.student_id = u.id LEFT JOIN topic_info t ON t.id = a.topic_id LEFT JOIN sys_user teacher ON teacher.id = a.teacher_id WHERE
1=1 u.id=#{scope.userId} a.teacher_id=#{scope.userId}
ORDER BY u.id

SELECT t.*, u.name teacher_name, m.name major_name, ( SELECT COUNT(*) FROM student_assignment a WHERE a.topic_id = t.id ) selected_count FROM topic_info t JOIN sys_user u ON u.id = t.teacher_id JOIN major m ON m.id = t.major_id WHERE
1=1 t.status='已通过' t.teacher_id=#{scope.userId}
ORDER BY t.id DESC

SELECT s.*, t.title, t.teacher_id, u.name student_name, teacher.name teacher_name FROM topic_selection s JOIN topic_info t ON t.id = s.topic_id JOIN sys_user u ON u.id = s.student_id JOIN sys_user teacher ON teacher.id = t.teacher_id WHERE
1=1 s.student_id=#{scope.userId} t.teacher_id=#{scope.userId}
ORDER BY s.id DESC

SELECT summary.name, COUNT(*) student_count, ROUND(AVG(summary.progress)) average_progress, SUM(summary.archived) archive_count, ROUND(AVG(summary.total_score), 2) average_score FROM ( SELECT COALESCE(
m.name c.name teacher.name
, '未分配') name, ROUND( ( CASE WHEN a.topic_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM task_book material WHERE material.student_id = u.id AND material.stage = 'task' AND material.status = '已通过' AND NOT EXISTS ( SELECT 1 FROM task_book newer WHERE newer.student_id = u.id AND newer.stage = material.stage AND newer.version > material.version ) ) THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM proposal_report material WHERE material.student_id = u.id AND material.stage = 'proposal' AND material.status = '已通过' AND NOT EXISTS ( SELECT 1 FROM proposal_report newer WHERE newer.student_id = u.id AND newer.stage = material.stage AND newer.version > material.version ) ) THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM midterm_check material WHERE material.student_id = u.id AND material.stage = 'midterm' AND material.status = '已通过' AND NOT EXISTS ( SELECT 1 FROM midterm_check newer WHERE newer.student_id = u.id AND newer.stage = material.stage AND newer.version > material.version ) ) THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM thesis_info material WHERE material.student_id = u.id AND material.stage = 'draft' AND material.status = '已通过' AND NOT EXISTS ( SELECT 1 FROM thesis_info newer WHERE newer.student_id = u.id AND newer.stage = material.stage AND newer.version > material.version ) ) THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM thesis_info material WHERE material.student_id = u.id AND material.stage = 'final' AND material.status = '已通过' AND NOT EXISTS ( SELECT 1 FROM thesis_info newer WHERE newer.student_id = u.id AND newer.stage = material.stage AND newer.version > material.version ) ) THEN 1 ELSE 0 END + CASE WHEN EXISTS ( SELECT 1 FROM defense_info d WHERE d.student_id = u.id AND d.status = '已完成' ) THEN 1 ELSE 0 END + CASE WHEN score.published = 1 THEN 1 ELSE 0 END + CASE WHEN archive.id IS NOT NULL THEN 1 ELSE 0 END ) * 100.0 / 9 ) progress, CASE WHEN archive.id IS NOT NULL THEN 1 ELSE 0 END archived,
CASE WHEN score.published=1 THEN score.total_score ELSE NULL END score.total_score
total_score FROM sys_user u JOIN sys_user_role ur ON ur.user_id = u.id JOIN sys_role r ON r.id = ur.role_id AND r.code = 'STUDENT' LEFT JOIN major m ON m.id = u.major_id LEFT JOIN school_class c ON c.id = u.class_id LEFT JOIN student_assignment a ON a.student_id = u.id LEFT JOIN sys_user teacher ON teacher.id = a.teacher_id LEFT JOIN score_info score ON score.student_id = u.id LEFT JOIN archive_record archive ON archive.student_id = u.id WHERE
1=1 u.id=#{scope.userId} a.teacher_id=#{scope.userId}
AND u.major_id=#{filters.majorId} AND u.class_id=#{filters.classId}
AND a.teacher_id=#{filters.teacherId}
AND u.cohort=#{filters.cohort} ) summary GROUP BY summary.name ORDER BY summary.name
